// native_time_register.cpp — registers every native of native_time_decl.h with
// bronze (embed::registerNative) under __bro_native.time. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_time from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.time.<Class>Proto for time.js to chain.

#include "native_time_decl.h"

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool getter(const char* path, void* f, const char* ret, std::string* error) {
    return ev::registerNative(path, f, sig(ret, {}, ev::NativeKind::Getter), error);
}

bool setter(const char* path, void* f, const char* type, std::string* error) {
    return ev::registerNative(path, f, sig("void", {type}, ev::NativeKind::Setter), error);
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_time(std::string* error) {
    const bool ok =
        getter("__bro_native.time.scale", p(&bro_time_scale_get), "f64", error) &&
        setter("__bro_native.time.scale", p(&bro_time_scale_set), "f64", error) &&
        getter("__bro_native.time.paused", p(&bro_time_paused_get), "bool", error) &&
        setter("__bro_native.time.paused", p(&bro_time_paused_set), "bool", error) &&
        getter("__bro_native.time.now", p(&bro_time_now_get), "f64", error);
    if (!ok) return false;
    return true;
}

}  // namespace bro::bronze_host
